const categoryFor = [
  "account",
  "listings",
  "buying-selling",
  "messaging",
  "safety-scams",
  "safety-scams",
  "safety-scams",
  "reporting-support",
  "reporting-support",
  "rules-policies",
];
export function author() {
  for (const locale of locales) {
    const rows = drafts[locale];
    if (!rows || rows.length !== articleIds.length)
      throw new Error(`Missing corpus: ${locale}`);
    mkdirSync(`content/${locale}`, { recursive: true });
    rows.forEach((row, i) => {
      const [title, summary, ...steps] = row.split("|");
      const id = articleIds[i];
      const path = `content/${locale}/${id}.md`;
      if (existsSync(path))
        throw new Error(`Refusing to replace editorial content: ${path}`);
      const meta = {
        id,
        slug: id,
        locale,
        title,
        summary,
        category: categoryFor[i],
        tags: [title, ...(i >= 4 && i <= 6 ? ["UPI", "QR", "OTP", "PIN"] : [])],
        reviewedAt: null,
        editorialStatus: "draft",
        sourceRefs: [
          i >= 4 && i <= 6
            ? "https://cybercrime.gov.in/"
            : i === 9
              ? "https://fairswap.in/grievance"
              : "https://fairswap.in/contact",
        ],
        relatedIds: [articleIds[i === 0 ? 8 : i === 9 ? 8 : i === 4 ? 2 : 4]],
      };
      writeFileSync(
        path,
        `---\n${JSON.stringify(meta, null, 2)}\n---\n\n${summary}\n\n## ${copy(locale).steps}\n\n${steps.map((s, j) => `${j + 1}. ${s}`).join("\n\n")}\n\n${copy(locale).unpublished}\n`,
        "utf8",
      );
    });
  }
}
